from pathlib import Path
import runpy

root=Path(__file__).resolve().parents[2]
ctx=runpy.run_path(str(root/'output/stock-preview/create-photo-designs.py'))
base,css,js=[ctx[k] for k in ['base','css','js']]
start=js.index('function photoCard(')
end=js.index('function renderChosen()',start)
card=js[start:end].replace('<button class="photo-card','<article tabindex="0" class="photo-card').replace('aria-pressed="${c.i===selected}"','aria-label="Chọn ${c.model} ${c.version}, VIN ${c.vin}"')
card=card.replace('</div></button>`}', '</div><div class="car-actions"><button class="btn" data-car-action="detail" data-car="${c.i}">Chi tiết ↗</button><button class="btn primary" data-car-action="hold" data-car="${c.i}" ${c.status===\'Chưa ghép\'?\'\':\'disabled\'}>Giữ xe (24h)</button></div></article>`}')
js=js[:start]+card+js[end:]
js=js.replace('renderChosen()}','''renderChosen();document.querySelectorAll('[data-car-action]').forEach(b=>b.onclick=e=>{e.stopPropagation();const c=cars[Number(b.dataset.car)];if(b.dataset.carAction==='hold')toast('Mẫu giữ xe 24h · '+c.model+' · '+c.vin+' · Chưa ghi vào hệ thống');else toast(c.model+' '+c.version+' · '+c.vin+' · '+c.color+' · '+c.park+' · Tồn '+c.age+' ngày')});document.querySelectorAll('.photo-card').forEach(c=>c.onkeydown=e=>{if(e.target===c&&(e.key==='Enter'||e.key===' ')){e.preventDefault();selected=Number(c.dataset.index);renderList()}})}''')
css+=r'''
.photo-header{padding:24px 28px 19px}.photo-header h1{font-size:25px}.photo-toolbar{padding:0 28px 17px}.photo-tabs{margin:0 28px 19px}.photo-body{margin:0 28px}.photo-bottom{display:none}.photo-workspace footer{padding:13px 28px}.photo-gallery{grid-template-columns:repeat(5,minmax(0,1fr));gap:14px;grid-auto-rows:253px;align-content:start}.photo-card{padding:15px 16px 12px;cursor:pointer}.photo-card .card-heading h3{font-size:16px}.photo-card h3 small{font-size:11px}.photo-card .status{font-size:9px;gap:5px}.photo-card img{height:92px;margin:5px 0 7px}.photo-card .car-vin{font-size:10px;letter-spacing:0}.photo-card .car-color{font-size:10px;margin-top:7px}.photo-card .car-footer{margin-top:9px;padding-top:9px;font-size:10px}.car-actions{display:flex;justify-content:space-between;gap:8px;border-top:1px solid var(--line);padding-top:10px;margin-top:10px}.car-actions .btn{padding:7px 10px;font-size:10px;border-radius:4px}.car-actions .primary{flex:1}.photo-card.selected:after{top:41px;right:12px;width:15px;height:15px;font-size:9px}.photo-gallery .photo-card:focus-visible{outline:2px solid #2967b7;outline-offset:2px}.photo-card .car-footer strong{font-size:10px}.photo-card .car-vin{color:#5a7395}.variant-18 .photo-gallery{grid-template-columns:repeat(3,minmax(0,1fr));grid-auto-rows:185px;gap:14px}.variant-18 .photo-card{display:grid;grid-template-columns:39% 61%;grid-template-rows:25px 1fr 27px 39px;padding:14px 17px 10px}.variant-18 .photo-card img{grid-column:1;grid-row:1/4;height:112px;margin:0;padding-right:17px;align-self:center}.variant-18 .card-heading{grid-column:2;grid-row:1}.variant-18 .car-info{grid-column:2;grid-row:2;align-self:center}.variant-18 .car-footer{grid-column:2;grid-row:3;margin:0;padding-top:6px}.variant-18 .car-actions{grid-column:1/3;grid-row:4;justify-content:flex-end;margin-top:6px;padding-top:8px}.variant-18 .car-actions .primary{flex:0}.variant-18 .photo-card.selected:after{left:10px;right:auto;top:10px}.variant-19 .photo-gallery{display:flex;flex-direction:column;gap:0}.variant-19 .photo-card{display:grid;grid-template-columns:142px 180px 1fr 170px 225px;align-items:center;gap:20px;border:0;border-bottom:1px solid var(--line);border-radius:0;min-height:81px;flex-shrink:0;padding:8px 16px}.variant-19 .photo-card:first-child{border-top:1px solid var(--line)}.variant-19 .photo-card img{grid-column:1;grid-row:1;height:68px;width:138px;margin:0}.variant-19 .card-heading{grid-column:2;grid-row:1;display:block}.variant-19 .card-heading h3{font-size:17px}.variant-19 .card-heading .status{margin-top:8px;font-size:10px}.variant-19 .car-info{grid-column:3;grid-row:1}.variant-19 .car-vin{font-size:11px}.variant-19 .car-color{font-size:11px;margin-top:8px}.variant-19 .car-footer{grid-column:4;grid-row:1;border:0;margin:0;padding:0;display:block;font-size:11px}.variant-19 .car-footer strong{display:block;margin-top:8px;font-size:11px}.variant-19 .car-actions{grid-column:5;grid-row:1;border:0;margin:0;padding:0;gap:8px}.variant-19 .car-actions .btn{font-size:11px;padding:9px 12px}.variant-19 .photo-card.selected{box-shadow:inset 3px 0 #2867b7;background:#edf3fe}.variant-19 .photo-card.selected:after{display:none}.compact-note{margin:17px 28px 0;padding-top:13px;border-top:1px solid var(--line);font-size:11px;color:#8a9bb0;display:flex;justify-content:space-between}.photo-body{margin-bottom:0}.photo-gallery{padding-bottom:12px}
'''
css += '.variant-17 .photo-gallery{grid-auto-rows:267px}.variant-18 .car-actions .primary{flex:0 0 auto;white-space:nowrap}.variant-18 .car-actions .btn{min-width:78px}.variant-18 .car-actions{padding-top:6px}.car-actions button{white-space:nowrap}'
js=js.replace("if(variant==='16')", "if(variant==='16')")
js=js.replace('renderList();\n', 'renderList();\n')
js += "document.querySelector('.photo-workspace footer').insertAdjacentHTML('beforebegin','<div class=\"compact-note\"><span>8 xe · Kho Thuận An · Thao tác trực tiếp trên từng xe</span><span>Dữ liệu minh họa · Chưa kết nối nghiệp vụ</span></div>');"
titles={'17':'Thẻ ảnh gọn 5 cột · Thao tác tại xe','18':'Thẻ ngang gọn 3 cột · Thao tác tại xe','19':'Danh sách ảnh gọn · Thao tác tại xe'}
for n,title in titles.items():
    html=base.replace('</style>',css+'</style>').replace('</body>','<script>'+js.replace('VARIANT',n).replace('TITLE',title.upper())+'</script></body>')
    html=html.replace('Kho xe · Mẫu giao diện','Kho xe · Mẫu '+n+' · '+title)
    (root/('public/previews/kho-xe-mau-'+n+'.html')).write_text(html,encoding='utf-8')
    print('Created compact variant '+n)
